+/// Balances rolled up to the first `depth` levels of the account name, sorted by name; zero roll-ups are left out.
+pub fn category_totals(ledger: &Ledger, depth: usize) -> Vec<(String, Amount)> {
+    assert!(depth > 0, "depth must be at least 1");
+    let mut totals: BTreeMap<String, Amount> = BTreeMap::new();
+    for (account, amount) in ledger.balances() {
+        let name = account.split(':').take(depth).collect::<Vec<_>>().join(":");
+        *totals.entry(name).or_default() += amount;
+    }
+    totals.into_iter().filter(|(_, a)| *a != Amount::ZERO).collect()
+}
+
+#[cfg(test)]
+mod category_tests {
+    use super::*;
+    use ledger_core::Transaction;
+
+    fn post(ledger: &mut Ledger, account: &str, cents: i64) {
+        let t = Transaction::new("2024-01-05", "t")
+            .post(account, Amount::from_cents(cents))
+            .post("assets:bank", Amount::from_cents(-cents));
+        ledger.record(t).unwrap();
+    }
+
+    #[test]
+    fn rolls_up_to_depth() {
+        let mut l = Ledger::new();
+        post(&mut l, "expenses:food:groceries", 1000);
+        post(&mut l, "expenses:food:dining", 300);
+        post(&mut l, "expenses:rent", 500);
+        assert_eq!(
+            category_totals(&l, 2),
+            vec![
+                ("assets:bank".to_string(), Amount::from_cents(-1800)),
+                ("expenses:food".to_string(), Amount::from_cents(1300)),
+                ("expenses:rent".to_string(), Amount::from_cents(500)),
+            ]
+        );
+        assert_eq!(
+            category_totals(&l, 1),
+            vec![
+                ("assets".to_string(), Amount::from_cents(-1800)),
+                ("expenses".to_string(), Amount::from_cents(1800)),
+            ]
+        );
+    }
+
+    #[test]
+    #[should_panic]
+    fn zero_depth_panics() {
+        category_totals(&Ledger::new(), 0);
+    }
+}
+
