+/// Account balances rolled up to the first `depth` levels of the account name, sorted by name, leaving out zero roll-ups. Panics if `depth` is 0.
+pub fn category_totals(ledger: &Ledger, depth: usize) -> Vec<(String, Amount)> {
+    assert!(depth > 0, "depth must be at least 1");
+    let mut totals: BTreeMap<String, Amount> = BTreeMap::new();
+    for (account, balance) in ledger.balances() {
+        let key: Vec<&str> = account.split(':').take(depth).collect();
+        *totals.entry(key.join(":")).or_default() += balance;
+    }
+    totals.into_iter().filter(|(_, total)| *total != Amount::ZERO).collect()
+}
