+    fn amt(s: &str) -> Amount {
+        Amount::parse(s).unwrap()
+    }
+
+    fn sample() -> Ledger {
+        let mut l = Ledger::new();
+        l.record(Transaction::new("2024-01-05", "groceries").post("expenses:food:groceries", amt("30.00")).post("assets:bank", amt("-30.00"))).unwrap();
+        l.record(Transaction::new("2024-01-06", "bakery").post("expenses:food:bakery", amt("5.00")).post("assets:cash", amt("-5.00"))).unwrap();
+        l.record(Transaction::new("2024-01-07", "rent").post("expenses:rent", amt("100.00")).post("assets:bank", amt("-100.00"))).unwrap();
+        l.record(Transaction::new("2024-01-08", "refund").post("expenses:food:bakery", amt("-5.00")).post("income:refunds", amt("5.00"))).unwrap();
